FuncDef.Code:
// Based on: "Generalized Distance Functions" by Akleman and Chen.
// From: http://mercury.sexy/hg_sdf/
// License: MIT
//
// Code by luk77 based on: 
// https://en.wikipedia.org/wiki/Truncated_cube
float hgsdfTruncatedCubeHard(vec3 p, float r)
{
    const float a = sqrt(2.0) - 1.0;

    const vec3 v0   = vec3( 1, 0, 0 );
    const vec3 v1   = vec3(-1, 0, 0 );
    const vec3 v2   = vec3( 0, 1, 0 );
    const vec3 v3   = vec3( 0,-1, 0 );
    const vec3 v4   = vec3( 0, 0, 1 );
    const vec3 v5   = vec3( 0, 0,-1 );
    const vec3 v6   = vec3( 1, 1, 1 );
    const vec3 v7   = vec3( 1, 1,-1 );
    const vec3 v8   = vec3( 1,-1, 1 );
    const vec3 v9   = vec3( 1,-1,-1 );
    const vec3 v10  = vec3(-1, 1, 1 );
    const vec3 v11  = vec3(-1, 1,-1 );
    const vec3 v12  = vec3(-1,-1, 1 );
    const vec3 v13  = vec3(-1,-1,-1 );

    float d = 0.0;
    d = max(d, (dot(p, v0 )));
    d = max(d, (dot(p, v1 )));
    d = max(d, (dot(p, v2 )));
    d = max(d, (dot(p, v3 )));
    d = max(d, (dot(p, v4 )));
    d = max(d, (dot(p, v5 )));
    d = max(d, (dot(p, v6 ) * a));
    d = max(d, (dot(p, v7 ) * a));
    d = max(d, (dot(p, v8 ) * a));
    d = max(d, (dot(p, v9 ) * a));
    d = max(d, (dot(p, v10) * a));
    d = max(d, (dot(p, v11) * a));
    d = max(d, (dot(p, v12) * a));
    d = max(d, (dot(p, v13) * a));

    return d - r;
}
